export const LIBRARY_SCHEMA_VERSION=2;
export const LIBRARY_SOURCES=Object.freeze(['core','user','imported','generated']);
export const ENRICHMENT_OPERATIONS=Object.freeze(['Expand','Diversify','Deepen','Fill Gaps']);
export const METADATA_ENUMS=Object.freeze({sociality:['solo','small-group','social','community'],environment:['indoor','outdoor','mixed'],activityLevel:['low','moderate','high'],orientation:['creative','technical','cultural','practical','analytical','physical']});
const slug=value=>String(value).toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
const item=(id,label,source='core',extra={})=>Object.freeze({id,label,source,...extra});
const entries=(familyId,labels,kind)=>labels.map((label,index)=>{const text=typeof label==='string'?label:label.label;const tags=typeof label==='string'?[slug(text),kind]:label.tags||[slug(text),kind];return item(`${familyId}-${slug(text)}-${index+1}`,text,'core',{tags,orientation:typeof label==='string'?(kind==='hobby'?'practical':'cultural'):label.orientation||(kind==='hobby'?'practical':'cultural'),...(kind==='hobby'?{sociality:label.sociality||'solo',environment:label.environment||'mixed',activityLevel:label.activityLevel||'moderate'}:{relatedHobbies:label.relatedHobbies||[]})})});
const family=(id,label,description,labels,tags,kind)=>({id,label,description,entries:entries(id,labels,kind),subcategories:[{id:`${id}-practice`,label:kind==='hobby'?'Practice types':'Topic threads',entryCount:labels.length}],tags:[...tags,kind],fixture:false,domain:kind});
const I=(id,label,description,labels,tags)=>family(id,label,description,labels,tags,'interest');
const H=(id,label,description,labels,tags)=>family(id,label,description,labels,tags,'hobby');

