const RELATED={photography:['street-photography','portrait-photography','film-photography','photo-editing','photo-walks'],technology:['programming','electronics-repair','pc-building','3d-printing','home-automation'],astronomy:['stargazing','astrophotography'],['japanese-culture']:['language-exchange','cultural-cooking'],['video-games']:['gaming','speedrunning','game-modding','game-development'],['urban-history']:['local-history-walks','genealogy-research','museum-visits'],['classical-music']:['classical-piano','choir','music-production']};
const relationLinks=Object.freeze(Object.fromEntries(Object.entries(RELATED).map(([interest,hobbies])=>[interest,hobbies.map(hobby=>({hobbyId:hobby,kind:'related',weight:.35}))])));
INTEREST_FAMILIES.forEach(group=>{group.entries=group.entries.map(entry=>relationLinks[slug(entry.label)]?{...entry,relatedHobbies:relationLinks[slug(entry.label)]}:entry)});
const STARTER={education:[{id:'learning-paths',label:'Learning Paths',description:'Reusable education and training concepts.',entries:[item('university','University'),item('apprenticeship','Apprenticeship'),item('self-taught','Self-taught')],subcategories:[],tags:['learning'],fixture:true}],skills:[{id:'creative-technical',label:'Creative & Technical',description:'Capabilities that can shape a character role.',entries:[item('writing','Writing'),item('coding','Coding'),item('photography-skill','Photography')],subcategories:[],tags:['capability'],fixture:true}],lifestyle:[{id:'daily-rhythm',label:'Daily Rhythm',description:'Habits and patterns that shape everyday life.',entries:[item('early-riser','Early riser'),item('night-owl','Night owl'),item('remote-work','Remote work')],subcategories:[],tags:['routine'],fixture:true}],social:[{id:'social-patterns',label:'Social Patterns',description:'Ways characters connect and participate.',entries:[item('close-circle','Close circle'),item('community-led','Community-led'),item('independent','Independent')],subcategories:[],tags:['community'],fixture:true}],media:[{id:'media-tastes',label:'Media Tastes',description:'Media habits and taste signals.',entries:[item('podcasts','Podcasts'),item('independent-cinema','Independent cinema'),item('magazines','Magazines')],subcategories:[],tags:['media'],fixture:true}]};
const countFamily=family=>family.entries?.length||family.entryCount||0;
export const coverageFor=count=>count===0?'poor':count<4?'low':count<12?'good':'healthy';
export function coverageForFamily(family){const count=countFamily(family);return {status:coverageFor(count),count,familyId:family.id,tagCount:new Set((family.entries||[]).flatMap(entry=>entry.tags||[])).size};}
export function coverageDiagnostics(registry,categoryId){const category=registry.find(item=>item.id===categoryId);if(!category)return null;const families=category.families.map(coverageForFamily);return {categoryId,category:coverageFor(category.entryCount),families,thinFamilies:families.filter(row=>row.status==='poor'||row.status==='low').map(row=>row.familyId)};}
function styleFamilies(stylePacks){return stylePacks.map(pack=>{const all=Object.values(pack.atoms).flat();return {id:pack.id,label:pack.name,description:pack.description,entries:all.map(atom=>item(atom.id,atom.value,'core',{tags:atom.tags||[]})),subcategories:Object.entries(pack.atoms).filter(([,atoms])=>atoms.length).map(([id,atoms])=>({id,label:id,entryCount:atoms.length})),tags:Object.entries(pack.influence).filter(([,level])=>level==='strong').map(([domain])=>domain),fixture:false};});}
function sceneFamilies(scenes){return [{id:'scene-settings',label:'Scene Settings',description:'The real settings currently available in PromptForge.',entries:scenes.map(scene=>item(scene.id,scene.name,'core',{description:scene.location,tags:[scene.activity,scene.ambience]})),subcategories:[],tags:['world','scene'],fixture:false}];}
function category(id,label,description,icon,families,layer='starter'){const entryCount=families.reduce((sum,family)=>sum+countFamily(family),0);return {id,label,description,icon,families,entryCount,familyCount:families.length,coverage:coverageFor(entryCount),layer};}
export function createLibraryRegistry({stylePacks=STYLE_PACK_LIST,scenes=[],state=null}={}){const character=state?.character;const nameEntries=['Nova','Maya','Ari','Sora'].map(value=>item(value.toLowerCase(),value));if(character?.name&&!nameEntries.some(entry=>entry.label.toLowerCase()===character.name.toLowerCase()))nameEntries.push(item(`user-${character.id}`,character.name,'user'));const occupationLabels=['Creative technologist','Editorial photographer','Architect','Indie designer'];if(character?.identity?.occupation&&!occupationLabels.includes(character.identity.occupation))occupationLabels.push(character.identity.occupation);const userInterests=(state?.interestState?.characterInterests||[]).map((value,index)=>item(`user-interest-${index}`,value,'user',{tags:[slug(value),'user-authored']}));return Object.freeze([
 category('overview','Overview','Library layers, coverage and content provenance.','◫',[{id:'core-layer',label:'Core Library',description:'Bundled content that application updates can improve safely.',entries:[],subcategories:[],tags:['core'],fixture:false},{id:'user-layer',label:'User Library',description:'Character-created and user-authored content stays distinct.',entries:userInterests,subcategories:[],tags:['user'],fixture:false},{id:'expansion-layer',label:'Expansion Layer',description:'Imported and generated candidates enter a review-first layer.',entries:[],subcategories:[],tags:['imported','generated'],fixture:false}],'mixed'),category('names','Names','Reusable identity seeds for Character Core.','Aa',[{id:'generator-seeds',label:'Generator Seeds',description:'Names currently used by Surprise Me.',entries:nameEntries,subcategories:[],tags:['identity'],fixture:false}],'core'),category('geography','Geography','World and scene-location foundations.','⌖',sceneFamilies(scenes),'core'),category('occupations','Occupations','Roles and professional identities.','▣',[{id:'generator-roles',label:'Generator Roles',description:'Occupations currently used by Surprise Me.',entries:occupationLabels.map((value,index)=>item(`role-${index}`,value,character?.identity?.occupation===value?'user':'core')),subcategories:[],tags:['identity'],fixture:false}],'core'),category('education','Education','Learning, qualifications and formative paths.','◇',STARTER.education),category('interests','Interests','Topics a character is curious about, follows or values.','♡',[...(userInterests.length?[{id:'active-character',label:'Active Character',description:'Interests saved on the current Character Core.',entries:userInterests,subcategories:[],tags:['user'],fixture:false}]:[]),...INTEREST_FAMILIES],'mixed'),category('hobbies','Hobbies','Activities a character actively does or practices repeatedly.','♧',HOBBY_FAMILIES,'core'),category('skills','Skills','Capabilities, craft and expertise.','✦',STARTER.skills),category('lifestyle','Lifestyle','Daily rhythms, preferences and patterns.','◯',STARTER.lifestyle),category('social-life','Social Life','Relationships, communities and social patterns.','♙',STARTER.social),category('media-tastes','Media & Tastes','Media habits and taste signals.','▤',STARTER.media),category('style-aesthetics','Style & Aesthetics','The live Style Pack catalogue and its resolver concepts.','✧',styleFamilies(stylePacks),'core')]);}
const searchable=value=>String(value||'').toLowerCase();
export function searchLibrary(registry,query='',filter='all'){const term=searchable(query.trim());return registry.filter(category=>filter==='all'||category.id===filter).map(category=>{const categoryHit=!term||searchable([category.label,category.description].join(' ')).includes(term);const families=category.families.filter(family=>categoryHit||searchable([family.label,family.description,...(family.tags||[]),...(family.subcategories||[]).map(row=>row.label),...(family.entries||[]).flatMap(entry=>[entry.label,entry.description,...(entry.tags||[]),...(entry.relatedHobbies||[])])].join(' ')).includes(term));return {...category,families};}).filter(category=>category.families.length||(!term&&category.familyCount===0));}
export function relatedHobbiesForInterest(interestId){return relationLinks[slug(interestId)]||[];}
export function validateCandidates(candidates,registry=[]){const seenIds=new Set(registry.flatMap(category=>category.families).flatMap(family=>family.entries).map(entry=>entry.id));const seenLabels=new Set(registry.flatMap(category=>category.families).flatMap(family=>family.entries).map(entry=>searchable(entry.label)));const errors=[],valid=[];for(const candidate of candidates||[]){const label=String(candidate?.label||'').trim();if(!candidate?.id||!label||!candidate.family){errors.push({candidate,reason:'missing required fields'});continue}if(seenIds.has(candidate.id)||valid.some(entry=>entry.id===candidate.id)){errors.push({candidate,reason:'duplicate ID'});continue}if(seenLabels.has(searchable(label))||valid.some(entry=>searchable(entry.label)===searchable(label))){errors.push({candidate,reason:'duplicate label'});continue}if(!candidate.source||!LIBRARY_SOURCES.includes(candidate.source)){errors.push({candidate,reason:'invalid source'});continue}if(candidate.metadata&&Object.entries(candidate.metadata).some(([key,value])=>METADATA_ENUMS[key]&&!METADATA_ENUMS[key].includes(value))){errors.push({candidate,reason:'invalid metadata enum'});continue}seenIds.add(candidate.id);seenLabels.add(searchable(label));valid.push({...candidate,reviewStatus:'pending'});}return {valid,errors};}
export function prepareEnrichmentOperation(operation,categoryId,familyId,registry){if(!ENRICHMENT_OPERATIONS.includes(operation))throw new Error(`Unsupported enrichment operation: ${operation}`);const category=registry.find(item=>item.id===categoryId),target=category?.families.find(item=>item.id===familyId);return {operation,categoryId,familyId,familyLabel:target?.label||null,status:'candidates-needed',mutatesCore:false,source:'generated',reviewStatus:'pending',request:{operation,targetFamily:target?.label||null}};}
export function validateLibraryRegistry(registry){const ids=new Set();for(const category of registry){if(ids.has(category.id))throw new Error(`Duplicate library category: ${category.id}`);ids.add(category.id);if(!category.label||!Array.isArray(category.families))throw new Error(`Invalid library category: ${category.id}`);const familyIds=new Set();for(const family of category.families){if(familyIds.has(family.id)||!family.id||!family.label||!Array.isArray(family.entries))throw new Error(`Invalid library family in ${category.id}`);familyIds.add(family.id);for(const entry of family.entries)if(!entry.id||!entry.label||!LIBRARY_SOURCES.includes(entry.source))throw new Error(`Invalid library entry in ${family.id}`);}}return {categoryCount:registry.length,entryCount:registry.reduce((sum,category)=>sum+category.entryCount,0)};}
